solution.solution.cpp:
#include <cctype>
#include <map>
#include <set>
#include <string>
#include <vector>

constexpr unsigned LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR = 0x100;
constexpr unsigned LOAD_LIBRARY_SEARCH_APPLICATION_DIR = 0x200;
constexpr unsigned LOAD_LIBRARY_SEARCH_USER_DIRS = 0x400;
constexpr unsigned LOAD_LIBRARY_SEARCH_SYSTEM32 = 0x800;
constexpr unsigned LOAD_LIBRARY_SEARCH_DEFAULT_DIRS = 0x1000;
constexpr unsigned ANY_SEARCH_FLAG = 0x100 | 0x200 | 0x400 | 0x800 | 0x1000;

struct World
{
    std::string appDir;
    std::string currentDir;
    std::vector<std::string> pathDirs;
    std::vector<std::string> userDirs;
    bool defaultDirsSet{ false };
    std::set<std::string> knownDlls;
    std::map<std::string, std::vector<std::string>> files;
};

namespace
{
    bool isFullPath(const std::string& p) { return p.size() >= 3 && std::isalpha(static_cast<unsigned char>(p[0])) && p[1] == ':' && p[2] == '\\'; }
    std::string nameOf(const std::string& path) { const auto s{ path.rfind('\\') }; return s == std::string::npos ? path : path.substr(s + 1); }
    std::string folderOf(const std::string& path) { const auto s{ path.rfind('\\') }; return s == std::string::npos ? "" : path.substr(0, s); }

    struct Loader
    {
        const World& w;
        unsigned flags;
        std::string dllLoadDir;
        std::map<std::string, std::string> loaded;     // name -> path
        std::vector<std::string> order;
        std::string missing;

        std::vector<std::string> folders() const
        {
            unsigned f{ flags & ANY_SEARCH_FLAG };
            if (!f && w.defaultDirsSet) f = LOAD_LIBRARY_SEARCH_DEFAULT_DIRS;
            if (!f)
            {
                std::vector<std::string> out{ w.appDir, "C:\\Windows\\System32", "C:\\Windows\\System", "C:\\Windows", w.currentDir };
                out.insert(out.end(), w.pathDirs.begin(), w.pathDirs.end());
                return out;
            }
            if (f & LOAD_LIBRARY_SEARCH_DEFAULT_DIRS) f |= LOAD_LIBRARY_SEARCH_APPLICATION_DIR | LOAD_LIBRARY_SEARCH_USER_DIRS | LOAD_LIBRARY_SEARCH_SYSTEM32;
            std::vector<std::string> out;
            if ((f & LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR) && !dllLoadDir.empty()) out.push_back(dllLoadDir);
            if (f & LOAD_LIBRARY_SEARCH_APPLICATION_DIR) out.push_back(w.appDir);
            if (f & LOAD_LIBRARY_SEARCH_USER_DIRS) out.insert(out.end(), w.userDirs.begin(), w.userDirs.end());
            if (f & LOAD_LIBRARY_SEARCH_SYSTEM32) out.push_back("C:\\Windows\\System32");
            return out;
        }

        std::string find(const std::string& request) const
        {
            if (isFullPath(request)) return w.files.count(request) ? request : "";
            const auto already{ loaded.find(request) };
            if (already != loaded.end()) return already->second;
            if (w.knownDlls.count(request)) return "C:\\Windows\\System32\\" + request;
            for (const std::string& folder : folders())
            {
                const std::string candidate{ folder + "\\" + request };
                if (w.files.count(candidate)) return candidate;
            }
            return "";
        }

        bool load(const std::string& request)
        {
            const std::string name{ nameOf(request) };
            if (loaded.count(name)) return true;
            const std::string path{ find(request) };
            if (path.empty()) { missing = name; return false; }
            loaded[name] = path;
            const auto imports{ w.files.find(path) };
            if (imports != w.files.end())
                for (const std::string& dependency : imports->second)
                    if (!load(dependency)) return false;
            order.push_back(name + " -> " + path);
            return true;
        }
    };
}

std::vector<std::string> loadLibraryEx(const World& w, const std::string& file, unsigned flags)
{
    Loader loader{ w, flags, isFullPath(file) ? folderOf(file) : "", {}, {}, {} };
    if (!loader.load(file)) return { "missing " + loader.missing };
    std::vector<std::string> result{ loader.order };
    result.push_back("ok");
    return result;
}

unitTests:
using Lines = std::vector<std::string>;
World game() {
    World w;
    w.appDir = "C:\\Game"; w.currentDir = "C:\\Downloads"; w.pathDirs = { "C:\\Tools" }; w.userDirs = { "D:\\Shared" };
    w.knownDlls = { "kernel32.dll" };
    w.files = {
        { "C:\\Game\\StoneMath.dll", { "kernel32.dll" } },
        { "C:\\Game\\plugins\\fog\\fog.dll", { "noise.dll", "StoneMath.dll" } },
        { "C:\\Game\\plugins\\fog\\noise.dll", {} },
        { "C:\\Downloads\\noise.dll", {} },
        { "C:\\Tools\\zlib.dll", {} },
        { "D:\\Shared\\zlib.dll", {} },
    };
    return w;
}
TEST("by name, standard search") { CHECK_EQ(loadLibraryEx(game(), "StoneMath.dll", 0), (Lines{ "kernel32.dll -> C:\\Windows\\System32\\kernel32.dll", "StoneMath.dll -> C:\\Game\\StoneMath.dll", "ok" })); }
TEST("a plugin without flags finds the planted noise.dll") { CHECK_EQ(loadLibraryEx(game(), "C:\\Game\\plugins\\fog\\fog.dll", 0), (Lines{ "noise.dll -> C:\\Downloads\\noise.dll", "kernel32.dll -> C:\\Windows\\System32\\kernel32.dll", "StoneMath.dll -> C:\\Game\\StoneMath.dll", "fog.dll -> C:\\Game\\plugins\\fog\\fog.dll", "ok" })); }
TEST("with DLL_LOAD_DIR the plugin finds its own noise.dll") { CHECK_EQ(loadLibraryEx(game(), "C:\\Game\\plugins\\fog\\fog.dll", LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR | LOAD_LIBRARY_SEARCH_DEFAULT_DIRS), (Lines{ "noise.dll -> C:\\Game\\plugins\\fog\\noise.dll", "kernel32.dll -> C:\\Windows\\System32\\kernel32.dll", "StoneMath.dll -> C:\\Game\\StoneMath.dll", "fog.dll -> C:\\Game\\plugins\\fog\\fog.dll", "ok" })); }
TEST("default dirs leave out the current directory") { World w = game(); w.defaultDirsSet = true; CHECK_EQ(loadLibraryEx(w, "C:\\Game\\plugins\\fog\\fog.dll", 0), (Lines{ "missing noise.dll" })); }
TEST("user dirs come before PATH would") { World w = game(); w.defaultDirsSet = true; CHECK_EQ(loadLibraryEx(w, "zlib.dll", 0), (Lines{ "zlib.dll -> D:\\Shared\\zlib.dll", "ok" })); CHECK_EQ(loadLibraryEx(game(), "zlib.dll", 0), (Lines{ "zlib.dll -> C:\\Tools\\zlib.dll", "ok" })); }
TEST("full path that does not exist") { CHECK_EQ(loadLibraryEx(game(), "C:\\Game\\nope.dll", 0), (Lines{ "missing nope.dll" })); }
TEST("missing dependency") { World w = game(); w.files["C:\\Game\\StoneMath.dll"] = { "audio.dll" }; CHECK_EQ(loadLibraryEx(w, "StoneMath.dll", 0), (Lines{ "missing audio.dll" })); }

